DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20240426033523_InitialCreate') THEN
    CREATE TABLE "Games" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "Name" text NOT NULL,
        "Date" date NOT NULL,
        "GameType" integer NOT NULL,
        "HomeId" bigint NOT NULL,
        "AwayId" bigint NOT NULL,
        "ScheduledTime" timestamp with time zone NOT NULL,
        "StartTime" timestamp with time zone,
        "EndTime" timestamp with time zone,
        "LocationId" bigint,
        "HomeScore" integer,
        "AwayScore" integer,
        "WinningTeamId" bigint,
        "WinningPitcherId" bigint,
        "LosingPitcherId" bigint,
        "SavingPitcherId" bigint,
        CONSTRAINT "PK_Games" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Games_Parks_LocationId" FOREIGN KEY ("LocationId") REFERENCES "Parks" ("Id"),
        CONSTRAINT "FK_Games_Players_LosingPitcherId" FOREIGN KEY ("LosingPitcherId") REFERENCES "Players" ("Id"),
        CONSTRAINT "FK_Games_Players_SavingPitcherId" FOREIGN KEY ("SavingPitcherId") REFERENCES "Players" ("Id"),
        CONSTRAINT "FK_Games_Players_WinningPitcherId" FOREIGN KEY ("WinningPitcherId") REFERENCES "Players" ("Id"),
        CONSTRAINT "FK_Games_Teams_AwayId" FOREIGN KEY ("AwayId") REFERENCES "Teams" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Games_Teams_HomeId" FOREIGN KEY ("HomeId") REFERENCES "Teams" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Games_Teams_WinningTeamId" FOREIGN KEY ("WinningTeamId") REFERENCES "Teams" ("Id")
    );
    END IF;
END $EF$;

